#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr = (int*)malloc(5 * sizeof(int));  // Allocate initial memory for 5 integers
    if (arr == NULL) {
        printf("Allocation failed\n");
        return 1;
    }

    for(int i = 0; i < 5; i++) {
        arr[i] = i;  // Initialize the first 5 elements
    }

    arr = (int*)realloc(arr, 10 * sizeof(int));  // Resize to hold 10 integers
    if (arr == NULL) {
        printf("Reallocation failed\n");
        return 1;
    }

    for(int i = 5; i < 10; i++) {
        arr[i] = i;  // Initialize the new elements
    }

    for(int i = 0; i < 10; i++) {
        printf("%d ", arr[i]);  // Print the array
    }
    printf("\n");

    free(arr);  // Free the memory
    return 0;
}
